#头文件 #include &#34;co/def.h&#34; #整型别名 typedef int8_t int8; typedef int16_t int16; typedef int32_t int32; typedef int64_t int64; typedef uint8_t uint8; typedef uint16_t uint16; typedef uint32_t uint32; typedef uint64_t uint64; 定义在全局命名空间。 #整型极值常量 namespace co { constexpr uint8 max_uint8 = (uint8) ~((uint8) 0); constexpr uint16 max_uint16 = (uint16) ~((uint16)0); constexpr uint32 max_uint32 = (uint32) ~((uint32)0); constexpr uint64 max_uint64 = (uint64) ~((uint64)0); constexpr int8 max_int8 = (int8) (max_uint8 &gt;&gt; 1); constexpr int16 max_int16 = (int16) (max_uint16 &gt;&gt; 1); constexpr int32 max_int32 = (int32) (max_uint32 &gt;&gt; 1); constexpr int64 max_int64 = (int64) (max_uint64 &gt;&gt; 1); constexpr int8 min_int8 = (int8) ~max_int8; constexpr int16 min_int16 = (int16) ~max_int16; constexpr int32 min_int32 = (int32) ~max_int32; constexpr int64 min_int64 = (int64) ~max_int64; } // co 定义在 co 命名空间，均为 constexpr。 示例:
#include &#34;co/def.h&#34; #include &#34;co/print.h&#34; int main() { co::println(&#34;max_uint32 = &#34;, co::max_uint32); co::println(&#34;max_int32 = &#34;, co::max_int32); co::println(&#34;min_int32 = &#34;, co::min_int32); return 0; } #缓存行大小 提供编译期常量 co::cache_line_size，常用于内存对齐、避免伪共享。各架构取值如下：
架构 co::cache_line_size S390X 256 PowerPC64 128 ARM64 128 其它（x86、x64 等） 64 co::cache_line_size 可能大于实际缓存行大小，对齐或填充时会多占少量内存，通常影响较小。 示例:
// 分配缓存行对齐的内存 co::alloc(n, co::cache_line_size); #宏 #架构 #if SIZE_MAX == UINT64_MAX #define __arch64 1 #elif SIZE_MAX == UINT32_MAX #define __arch32 1 #else #error &#34;platform not supported&#34; #endif 64 位平台定义 __arch64 宏，值为 1； 32 位平台定义 __arch32 宏，值为 1； #缓存行对齐 #ifndef __cacheline_aligned #define __cacheline_aligned alignas(co::cache_line_size) #endif __cacheline_aligned 宏让变量或结构体按缓存行对齐。 示例：
struct __cacheline_aligned Foo { int x; }; #线程局部存储 #ifdef _MSC_VER #ifndef __thread #define __thread __declspec(thread) #endif #endif __thread 用于定义线程局部变量； gcc/clang 已内置 __thread，Windows 上(使用 MSVC)将其定义为 __declspec(thread)。 示例：
__thread int g_v; __thread void* g_p; #__unlikely 提示编译器条件为假概率更高。 旧版本中名为 unlikey，为避免与 C++20 [[unlikely]] 冲突，改为 __unlikely。 示例：
fs::file f(&#34;xx.log&#34;, &#39;r&#39;); if (__unlikely(!f)) co::println(&#34;open file failed&#34;);

#头文件 #include &#34;co/sock.h&#34; API 在 co 命名空间。使用前需在 main 开头调用 flag::parse(argc, argv);。
sock_t 在全局命名空间。
#概述 基于协程的 socket API。 I/O 相关 API 不阻塞调度线程，必须在协程中调用。 出错可用 co::error() / co::strerror() 获取错误信息。 #地址 co::sockaddr struct sockaddr { sockaddr(); sockaddr(const char* host, uint16 port); bool valid() const; int af() const; }; 支持 IPv4、IPv6、域名解析。 af() 返回 AF_INET 或 AF_INET6。 可直接打印，格式 127.0.0.1:8080。 #I/O 事件类型 enum ev_t { ev_read = 1, ev_write = 2, }; 不支持按位或组合。 #创建 socket sock_t co::tcp_socket(int af=0); sock_t co::udp_socket(int af=0); sock_t co::tcp_server_socket(const char* host, uint16 port, int backlog=4096); af=0 默认 AF_INET。 创建的 socket 已是 non-block。 tcp_server_socket：创建 TCP socket，绑定地址并监听。 #socket 操作 int co::close(sock_t fd, int ms=0); int co::bind(sock_t fd, const sockaddr&amp; addr); int co::listen(sock_t fd, int backlog=4096); int co::connect(sock_t fd, const sockaddr&amp; addr, int ms=-1); sock_t co::accept(sock_t fd, sockaddr* addr=nullptr); close(fd, ms)：延迟 ms 毫秒关闭，防恶意攻击。 connect：ms=-1 不超时，超时错误码 ETIMEDOUT。 accept 成功返回 socket，错误返回 (sock_t)-1，其余成功返回 0，错误返回 -1。 #收发 int co::recv(sock_t fd, void* buf, int n, int ms=-1); int co::recvn(sock_t fd, void* buf, int n, int ms=-1); int co::recvfrom(sock_t fd, void* buf, int n, sockaddr&amp; addr, int ms=-1); int co::send(sock_t fd, const void* buf, int n, int ms=-1); int co::sendto(sock_t fd, const void* buf, int n, const sockaddr&amp; addr, int ms=-1); recv：单次读取，可能少于 n。 recvn：精确读取 n 字节，适合固定长度头部协议。 recvfrom：UDP 接收；函数返回时，addr 中填充发送方地址。 send：成功返回 n 表示全部发送；出错或超时状态未定义。 sendto：UDP 发送。 ms=-1 不超时，超时错误码 ETIMEDOUT。 #socket 选项 void co::set_reuseaddr(sock_t fd); void co::set_tcp_nodelay(sock_t fd); void co::set_tcp_keepalive(sock_t fd); void co::set_send_buffer_size(sock_t fd, int n); void co::set_recv_buffer_size(sock_t fd, int n); void co::set_nonblock(sock_t fd); void co::set_cloexec(sock_t fd); // 非 Windows set_send_buffer_size / set_recv_buffer_size 必须在连接前调用。 #其它 int co::reset_tcp_socket(sock_t fd, int ms=0); co::sockaddr co::peeraddr(sock_t fd); reset_tcp_socket：重置连接，不进 timed_wait，一般用于服务端。 peeraddr：返回对端地址。 #示例 #TCP 客户端 #include &#34;co/co.h&#34; #include &#34;co/sock.h&#34; #include &#34;co/print.h&#34; int main(int argc, char** argv) { flag::parse(argc, argv); go([] { co::sockaddr addr(&#34;127.0.0.1&#34;, 8080); sock_t fd = co::tcp_socket(addr.af()); int r = co::connect(fd, addr, 3000); if (r != 0) { co::println(&#34;connect failed: &#34;, co::strerror()); co::close(fd); return; } const char* msg = &#34;hello&#34;; r = co::send(fd, msg, 5, 3000); co::println(&#34;sent &#34;, r, &#34; bytes&#34;); char buf[128]; r = co::recv(fd, buf, sizeof(buf), 3000); if (r &gt; 0) co::println(&#34;recv: &#34;, co::string(buf, r)); co::close(fd); }); co::sleep(5000); return 0; } #TCP 服务端 #include &#34;co/co.h&#34; #include &#34;co/sock.h&#34; #include &#34;co/print.h&#34; int main(int argc, char** argv) { flag::parse(argc, argv); go([] { sock_t s = co::tcp_server_socket(&#34;0.0.0.0&#34;, 8080); if (s == (sock_t)-1) { co::println(&#34;listen failed: &#34;, co::strerror()); return; } while (true) { co::sockaddr addr; sock_t fd = co::accept(s, &amp;addr); if (fd == (sock_t)-1) break; go([fd, addr] { co::println(&#34;accepted: &#34;, addr); char buf[1024]; int n = co::recvn(fd, buf, 4); if (n == 4) { uint32 body_len = *(uint32*)buf; co::string body; body.resize(body_len); co::recvn(fd, body.data(), body_len); co::println(&#34;body: &#34;, body); } co::close(fd); }); } co::close(s); }); co::sleep(60000); return 0; } #UDP #include &#34;co/co.h&#34; #include &#34;co/sock.h&#34; #include &#34;co/print.h&#34; int main(int argc, char** argv) { flag::parse(argc, argv); go([] { sock_t fd = co::udp_socket(); co::sockaddr addr(&#34;127.0.0.1&#34;, 8080); const char* msg = &#34;ping&#34;; co::sendto(fd, msg, 4, addr, 3000); char buf[128]; co::sockaddr peer; int n = co::recvfrom(fd, buf, sizeof(buf), peer, 3000); if (n &gt; 0) co::print(&#34;recvfrom &#34;, peer, &#34;: &#34;, co::string(buf, n), &#39;\n&#39;); co::close(fd); }); co::sleep(5000); return 0; }

#头文件 #include &#34;co/time.h&#34; 无需 flag::parse。
sleep 在 time 命名空间，其余在 co 命名空间。
#当前时间 co::now struct Now { static int64 ns(); // 纳秒，可能 2262 年溢出 static int64 us(); // 微秒 static int64 ms(); // 毫秒 static co::string str(const char* fmt=&#34;%Y-%m-%d %H:%M:%S&#34;); }; ns() / us() / ms() 返回 Unix epoch 时间戳（UTC）。 str() 基于 strftime，返回本地时间字符串。 #单调时钟 co::mono_time struct MonoTime { static int64 ns(); static int64 us(); static int64 ms(); }; 基于 std::chrono::steady_clock。 单调递增，适合测时间差。 #计时器 co::timer struct timer { timer(); void restart(); int64 ns() const; int64 us() const; int64 ms() const; }; 构造时记录起点。 restart() 重置起点。 ns() / us() / ms() 返回从起点到现在的耗时。 基于 mono_time。 #睡眠 time::sleep void time::sleep(uint32 ms); 单位毫秒。 线程级 sleep，会阻塞当前线程。 不能在协程中使用，协程中应用 co::sleep。 #示例 #include &#34;co/time.h&#34; #include &#34;co/print.h&#34; int main() { co::println(&#34;now.ns() = &#34;, co::now.ns()); co::println(&#34;now.us() = &#34;, co::now.us()); co::println(&#34;now.ms() = &#34;, co::now.ms()); co::println(&#34;now.str() = &#34;, co::now.str()); co::println(&#34;now.str(%Y%m%d) = &#34;, co::now.str(&#34;%Y%m%d&#34;)); co::println(&#34;mono.ns() = &#34;, co::mono_time.ns()); co::println(&#34;mono.us() = &#34;, co::mono_time.us()); co::println(&#34;mono.ms() = &#34;, co::mono_time.ms()); co::timer t; time::sleep(100); co::println(&#34;elapsed ns = &#34;, t.ns()); co::println(&#34;elapsed us = &#34;, t.us()); co::println(&#34;elapsed ms = &#34;, t.ms()); t.restart(); time::sleep(50); co::println(&#34;after restart, ms = &#34;, t.ms()); return 0; }
